import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Dashboards","description":"","frontmatter":{"title":"Dashboards","covers":{"screens":["SCR-024","SCR-056"],"stories":["US-055","US-056","US-057","US-058","US-059","US-060","US-062"]}},"headers":[],"relativePath":"de/usage/dashboards.md","filePath":"de/usage/dashboards.md"}`),a={name:`de/usage/dashboards.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="dashboards" tabindex="-1">Dashboards <a class="header-anchor" href="#dashboards" aria-label="Permalink to “Dashboards”">​</a></h1><p>Ein Dashboard gibt Leserinnen und Lesern einen strukturierten Blick auf die Architektur. Es ordnet <strong>Widgets</strong> in einem Raster aus 12 Spalten an: Text-Widgets mit formatierten Hinweisen, Tabellen-Widgets, die die Zeilen eines <a href="./catalogs">Katalogs</a> zeigen, KPI-Widgets mit einer Kennzahl und Diagramm-Widgets mit Verteilungen. Um Dashboards zu sehen und persönliche anzulegen, brauchst du die Berechtigung <code>entity:read</code> (zum Beispiel die Rolle <code>viewer</code>); geteilte Dashboards brauchen <code>dashboard:manage</code> (Rolle <code>enterprise-architect</code>).</p><p>Es gibt zwei Arten von Dashboards:</p><ul><li><strong>Geteilte</strong> Dashboards sind für alle Leser der Instanz sichtbar. Jede Person mit <code>dashboard:manage</code> kann jedes geteilte Dashboard ändern und löschen.</li><li><strong>Persönliche</strong> Dashboards sind nur für dich sichtbar. Niemand sonst sieht sie in einer Liste, und ihre Adresse antwortet <em>Das Dashboard existiert nicht oder du darfst es nicht sehen</em>. Ausnahme sind Administratoren mit der Berechtigung <code>settings:manage</code>: Sie sehen die persönlichen Dashboards anderer Personen in der Liste, mit dem Eigentümer markiert, und können sie lesen, aber nie ändern oder löschen.</li></ul><p>Service-Accounts haben keinen Zugriff auf Dashboards.</p><h2 id="die-seite-dashboards" tabindex="-1">Die Seite Dashboards <a class="header-anchor" href="#die-seite-dashboards" aria-label="Permalink to “Die Seite Dashboards”">​</a></h2><p>Wähle <em>Dashboards</em> in der Kopfzeile. Die Seite listet die Dashboards, die du sehen darfst, mit ihrer Sichtbarkeit (<em>Geteilt</em> oder <em>Persönlich</em>), dem Eigentümer und der Anzahl der Widgets. Wähle ein Dashboard, um es zu öffnen.</p><h2 id="ein-dashboard-anlegen" tabindex="-1">Ein Dashboard anlegen <a class="header-anchor" href="#ein-dashboard-anlegen" aria-label="Permalink to “Ein Dashboard anlegen”">​</a></h2><ol><li><p>Wähle auf der Seite <em>Dashboards</em> die Schaltfläche <em>Dashboard anlegen</em>.</p></li><li><p>Fülle den Dialog aus:</p><table tabindex="0"><thead><tr><th>Feld</th><th>Bedeutung</th></tr></thead><tbody><tr><td>Name</td><td>Pflicht, 1 bis 200 Zeichen; eindeutig unter den geteilten Dashboards und unter deinen persönlichen Dashboards, unabhängig von Groß- und Kleinschreibung</td></tr><tr><td>Beschreibung</td><td>optional, bis zu 1000 Zeichen</td></tr><tr><td>Sichtbarkeit</td><td><em>Geteilt</em>: für alle Leser sichtbar (braucht die Berechtigung, Dashboards zu verwalten); <em>Persönlich</em>: nur für dich sichtbar</td></tr></tbody></table></li><li><p>Wähle <em>Dashboard anlegen</em>. Das neue Dashboard öffnet sich mit dem Hinweis „Noch keine Widgets. Widget hinzufügen.&quot;</p></li></ol><p>Ist der Name schon vergeben, sagt der Dialog das. Ohne die Berechtigung, Dashboards zu verwalten, ist <em>Geteilt</em> nicht wählbar.</p><h2 id="ein-dashboard-lesen" tabindex="-1">Ein Dashboard lesen <a class="header-anchor" href="#ein-dashboard-lesen" aria-label="Permalink to “Ein Dashboard lesen”">​</a></h2><p>Ein Dashboard zeigt seine Widgets an ihren Positionen. Die Daten werden bei jedem Öffnen berechnet, mit deinen eigenen Berechtigungen: Ein Tabellen-Widget zeigt den Katalog so, wie du ihn sehen darfst, einschließlich gesperrter Spalten (siehe <a href="./../administration/property-visibility">Sichtbarkeit von Eigenschaften</a>). Wer im <a href="./portal#dashboards">Portal</a> arbeitet, sieht dieselben Dashboards dort schreibgeschützt.</p><ul><li>Ein <strong>Text-Widget</strong> zeigt sein Markdown als formatierten Text.</li><li>Ein <strong>Tabellen-Widget</strong> zeigt die Zeilen seines Katalogs, mit den Spalten seiner gespeicherten Ansicht, falls es eine hat. Unter der Tabelle wechseln <em>Seite 1 von 5 · 47 Einträge</em> und die Seitenleiste zwischen den Seiten.</li><li>Ein <strong>KPI-Widget</strong> zeigt einen aggregierten Wert mit seiner Einheit, zum Beispiel <em>42.000.000 CHF</em>. Mit einem Zielwert zeigt es auch das Ziel, die Differenz und einen Trend als Symbol und Text (<em>8.000.000 CHF unter dem Ziel</em>). Ohne Wert (zum Beispiel hat keine Entität einen Wert der Eigenschaft) zeigt es <em>– (keine Daten)</em>; wird nichts gezählt, ist das Ergebnis 0. Mit dem Vergleich <em>Mit dem Wert vor 30 Tagen</em> zeigt es zusätzlich <em>Vor 30 Tagen (20.10.2026): 35.000.000 CHF</em> (das Datum des Werts steht im Text), die Differenz mit Vorzeichen samt Prozentwert und einen Trend als Symbol und Text (<em>Zunahme: +7.000.000 CHF (+20 %)</em>, <em>Abnahme: …</em> oder <em>Unverändert</em>); der Prozentwert entfällt, wenn der Wert vor 30 Tagen 0 war. Hatte damals keine Entität einen Wert, zeigt das KPI <em>Kein Vergleichswert</em>; eine Anzahl wird mit 0 verglichen.</li><li>Ein <strong>Diagramm-Widget</strong> zeigt eine Aggregation als Balken, Linien, Flächen, Kreis- oder Ringsegmente oder als Treemap, mit Legende und Datenbeschriftungen, wenn konfiguriert. Fahre über eine Gruppe oder fokussiere sie, um ihren Wert zu sehen. Namen erscheinen in deiner Sprache; Entitäten ohne Wert bilden die Gruppe <em>(keine)</em>, und nur die 50 größten Gruppen werden gezeigt, der Rest wird als <em>Andere</em> summiert. Für Screenreader gibt es eine Tabelle mit denselben Zahlen.</li><li>Ein KPI- oder Diagramm-Widget, das eine Eigenschaft aggregiert, deren Werte du nicht für alle Entitäten lesen darfst (siehe <a href="./../administration/property-visibility">Sichtbarkeit von Eigenschaften</a>), zeigt <em>Die Werte dieser Eigenschaft sind nicht für alle Elemente lesbar, daher wird kein Aggregat angezeigt.</em> Rollen, die die Sichtbarkeit übersteuern dürfen, heben das nicht auf. Entitäten zu zählen und nach Elementtyp oder Ebene zu gruppieren ist immer möglich.</li><li>Ein KPI- oder Diagramm-Widget, dessen Elementtyp oder Eigenschaft inzwischen aus dem Metamodell entfernt wurde, zeigt <em>Das Widget passt nicht mehr zum Metamodell. Bearbeite oder entferne es.</em> Die anderen Widgets bleiben unberührt, und kein Widget wird automatisch entfernt. Eine gelöschte Architekturebene verschiebt ihre Elementtypen in die Gruppe <em>(keine)</em>.</li><li>Ein Widget, dessen Katalog nicht mehr existiert oder für dich nicht sichtbar ist, zeigt <em>Katalog nicht gefunden</em>; ein Widget, dessen gespeicherte Ansicht fehlt, zeigt <em>Gespeicherte Ansicht nicht gefunden</em>. Die anderen Widgets bleiben unberührt.</li><li>Widgets, die sich überlappen, haben einen roten Rand und den Hinweis <em>Überlappt ein anderes Widget</em>.</li></ul><h2 id="ein-dashboard-andern" tabindex="-1">Ein Dashboard ändern <a class="header-anchor" href="#ein-dashboard-andern" aria-label="Permalink to “Ein Dashboard ändern”">​</a></h2><p>Darfst du ein Dashboard ändern, hat die Seite die Schaltfläche <em>Bearbeiten</em>. Im Bearbeitungsmodus kannst du:</p><ul><li><strong>Widget hinzufügen</strong>: den Typ <em>Text</em>, <em>Tabelle</em>, <em>KPI</em> oder <em>Diagramm</em> wählen, einen Titel mit 1 bis 150 Zeichen eingeben und das Widget konfigurieren (siehe unten). Neue Widgets landen unter den vorhandenen und lassen sich dann anordnen. Ein Dashboard hat höchstens 50 Widgets.</li><li>Ein Widget mit den Schaltflächen in seiner Kopfzeile <strong>bearbeiten</strong> oder <strong>entfernen</strong>. Der Typ eines Widgets ändert sich nicht; entferne es und füge ein neues hinzu.</li><li>Das Dashboard <strong>umbenennen</strong>, seine Beschreibung ändern oder <strong>mit allen teilen</strong>: Ein persönliches Dashboard wird geteilt, wenn du <code>dashboard:manage</code> hast, der Name unter den geteilten Dashboards frei ist und kein Widget einen persönlichen Katalog zeigt. Ein geteiltes Dashboard wird nicht wieder persönlich.</li><li>Das Dashboard mit allen Widgets <strong>löschen</strong>, nach einer Rückfrage.</li></ul><p>Mit <em>Fertig</em> verlässt du den Bearbeitungsmodus.</p><h3 id="text-widgets" tabindex="-1">Text-Widgets <a class="header-anchor" href="#text-widgets" aria-label="Permalink to “Text-Widgets”">​</a></h3><p>Ein Text-Widget enthält Markdown mit bis zu 10000 Zeichen, zum Beispiel methodische Hinweise: fetten und kursiven Text, Listen, Zitate, Überschriften, Tabellen und Links. Links funktionieren nur mit <code>http</code>, <code>https</code> und <code>mailto</code>. Rohes HTML wird nicht interpretiert; es erscheint als Text. Skripte, Event-Handler und andere Schemata wie <code>javascript:</code> laufen nie.</p><h3 id="tabellen-widgets" tabindex="-1">Tabellen-Widgets <a class="header-anchor" href="#tabellen-widgets" aria-label="Permalink to “Tabellen-Widgets”">​</a></h3><p>Ein Tabellen-Widget braucht einen Katalog, den du sehen darfst. Auf einem geteilten Dashboard lassen sich nur geteilte Kataloge wählen, damit alle Leser Daten sehen; ein persönliches Dashboard kann auch deine persönlichen Kataloge zeigen. Wähle optional eine gespeicherte Ansicht dieses Katalogs für seine Spalten und die Zeilen pro Seite (5 bis 100, Standard 10). Das Widget liest immer aktuelle Daten über die Katalogabfrage, als der Leser.</p><h3 id="kpi-und-diagramm-widgets" tabindex="-1">KPI- und Diagramm-Widgets <a class="header-anchor" href="#kpi-und-diagramm-widgets" aria-label="Permalink to “KPI- und Diagramm-Widgets”">​</a></h3><p>Beide aggregieren die Entitäten eines <strong>Elementtyps</strong>, Untertypen eingeschlossen; gelöschte Entitäten und die Änderungen von Lösungen werden nicht gezählt. Wähle:</p><table tabindex="0"><thead><tr><th>Feld</th><th>Bedeutung</th></tr></thead><tbody><tr><td>Elementtyp</td><td>der Elementtyp, der aggregiert wird, oder <em>Alle Elementtypen</em> für eine Anzahl aller Entitäten</td></tr><tr><td>Funktion</td><td><em>Anzahl</em>, <em>Summe</em>, <em>Durchschnitt</em>, <em>Minimum</em> oder <em>Maximum</em>. Summe, Durchschnitt, Minimum und Maximum brauchen eine Eigenschaft vom Typ Zahl (Ganzzahl); eine Anzahl nimmt die Entitäten selbst oder eine beliebige zugeordnete Eigenschaft und zählt die Entitäten, die einen Wert davon haben</td></tr><tr><td>Eigenschaft</td><td>die Eigenschaft, die aggregiert wird; angeboten werden nur Eigenschaften, die dem Elementtyp zugeordnet sind</td></tr><tr><td>Einheit</td><td>optional, bis zu 20 Zeichen, hinter dem Wert angezeigt</td></tr></tbody></table><p>Wähle bei einem <strong>KPI-Widget</strong> den Vergleich <em>Mit Zielwert</em> und gib das Ziel ein, um die Differenz und den Trend zu sehen; oder wähle <em>Mit dem Wert vor 30 Tagen</em>, um mit dem Wert zu vergleichen, den dieselbe Aggregation 30 Tage zuvor hatte (genau 30 mal 24 Stunden). Dieser Wert wird aus dem Verlauf der Entitäten berechnet: die Entitäten, die damals existierten und noch nicht gelöscht waren, jeweils mit dem Wert der letzten Version bis dahin. Er verwendet das aktuelle Metamodell; eine seitdem erfolgte Änderung eines Elementtyps (zum Beispiel seines Basistyps) wird nicht rekonstruiert, der Vergleich ist dann näherungsweise. Es gelten dieselben Sichtbarkeitsregeln wie beim aktuellen Wert: Bei einer Eigenschaft, die du nicht für alle Entitäten lesen darfst, wird keiner der beiden Werte gezeigt. Diagramme haben keinen Vergleich.</p><p>Wähle bei einem <strong>Diagramm-Widget</strong> <em>Gruppieren nach</em>: eine Eigenschaft (vom Typ Text, Auswahl, Ja/Nein oder Referenz; eine Referenz gruppiert nach dem Namen der referenzierten Entität), den Elementtyp oder die Architekturebene. Entitäten eines Metatyps ohne Ebene bilden die Gruppe <em>(keine)</em>. Wähle den Diagrammtyp (<em>Balken</em>, <em>Linie</em>, <em>Fläche</em>, <em>Kreis</em>, <em>Ring</em> oder <em>Treemap</em>) und ob Legende und Datenbeschriftungen angezeigt werden. Ein Diagramm zeigt eine Datenreihe.</p><p>Ein neues Widget beginnt mit allen gezählten Entitäten und ein Diagramm mit der Gruppierung nach Elementtyp. Wechselst du den Elementtyp, entfallen eine Eigenschaft oder Gruppierung, die er nicht hat. Die Gruppierung nach dem Namen der Entitäten wird nicht angeboten.</p><h2 id="die-widgets-anordnen" tabindex="-1">Die Widgets anordnen <a class="header-anchor" href="#die-widgets-anordnen" aria-label="Permalink to “Die Widgets anordnen”">​</a></h2><p>Das Raster hat 12 Spalten. Ein Widget hat eine Spalte, eine Breite, eine Zeile und eine Höhe:</p><table tabindex="0"><thead><tr><th>Eigenschaft</th><th>Erlaubte Werte</th></tr></thead><tbody><tr><td>Spalte</td><td>1 bis 12</td></tr><tr><td>Breite</td><td>1 bis 12; Spalte + Breite höchstens 13</td></tr><tr><td>Zeile</td><td>1 bis 500</td></tr><tr><td>Höhe</td><td>1 bis 6 Zeilen</td></tr></tbody></table><p>Im Bearbeitungsmodus:</p><ul><li><strong>Ziehe</strong> ein Widget am Griff links von seinem Titel, um es zu verschieben, und ziehe die Ecke unten rechts, um seine Größe zu ändern.</li><li>Oder nutze die <strong>Anordnungsknöpfe</strong> unter einem Widget (nach links, rechts, oben, unten; eine Spalte schmaler oder breiter; eine Zeile niedriger oder höher) oder die <strong>Pfeiltasten</strong> auf dem Griff: Pfeiltasten verschieben das Widget, mit Umschalttaste ändern sie die Größe.</li></ul><p>Jede Änderung wird sofort gespeichert, als eine Anfrage. Würde ein Widget über Spalte 12 hinausreichen, sagt die Seite <em>Das Widget überschreitet die Rasterbreite</em> und speichert die Position nicht. Überlappungen sind erlaubt; der Editor markiert sie.</p><h2 id="anderungen-durch-mehrere-personen" tabindex="-1">Änderungen durch mehrere Personen <a class="header-anchor" href="#anderungen-durch-mehrere-personen" aria-label="Permalink to “Änderungen durch mehrere Personen”">​</a></h2><p>Jede Änderung bezieht sich auf die Version des Dashboards, die du geladen hast. Hat jemand anderes das Dashboard inzwischen geändert, lädt die Seite es neu und sagt das; wiederhole deine Änderung.</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to “API”">​</a></h2><p>Die Dashboards sind über <code>/dashboards</code> und <code>/views/dashboards</code> verfügbar (siehe die <a href="./../api/">API-Referenz</a>):</p><ul><li><code>GET /dashboards</code> und <code>POST /dashboards</code> listen und erstellen Dashboards; <code>PUT</code> und <code>DELETE /dashboards/{id}</code> ändern und löschen eines.</li><li><code>POST /dashboards/{id}/widgets</code>, <code>PUT</code> und <code>DELETE /dashboards/{id}/widgets/{widgetId}</code> ändern Widgets (ein KPI- oder Diagramm-Widget trägt die Eigenschaft <code>aggregation</code> mit <code>metatypeId</code>, <code>propertyDefId</code>, <code>function</code> und, bei einem Diagramm, <code>groupBy</code>), und <code>PUT /dashboards/{id}/layout</code> positioniert bis zu 50 Widgets in einer Anfrage. Jeder Schreibzugriff braucht den Header <code>If-Match</code> mit der gelesenen Version (<code>&quot;3&quot;</code>); ohne ihn lautet die Antwort 428, mit einer anderen Version 412. Die Antworten tragen die neue Version als <code>ETag</code>.</li><li><code>GET /views/dashboards/{id}</code> liefert die Konfiguration, <code>GET /views/dashboards/{id}/data</code> die Daten aller Widgets und <code>GET /views/dashboards/{id}/widgets/{widgetId}/data?page=</code> eine weitere Seite eines Tabellen-Widgets (ab 0). Die Daten eines KPI-Widgets haben <code>value</code> (null ohne Daten), <code>target</code> und, mit dem Vergleich <code>vs-previous-value</code>, <code>previousValue</code> (null, wenn damals keine Entität einen Wert hatte) und <code>previousAt</code> (der Zeitpunkt, 30 Tage vor der Anfrage), die eines Diagramm-Widgets <code>series</code> mit <code>kind</code>, <code>key</code>, <code>label</code>, <code>labelKey</code> und <code>value</code> je Gruppe; ein Widget, das nicht berechnet werden kann, hat den Status <code>error</code> mit dem Code <code>restricted</code> oder <code>invalid-configuration</code>.</li><li>Ein vergebener Name antwortet 422 mit dem Problemtyp <code>urn:oea:problem:dashboard-name-taken</code>; andere ungültige Eingaben antworten 422 mit <code>invalidFields</code>. Das persönliche Dashboard einer anderen Person antwortet 404.</li></ul>`,38)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};